import { Title } from "@solidjs/meta";
import { action, createAsync, query, useAction } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import { getRequestEvent } from "solid-js/web";
import {
  processContact,
  readContactForm,
  validateContact,
  type ContactErrors,
  type ContactResult,
  type ContactValues
} from "~/lib/contact";

// Result of a form posted to /contact without JavaScript (set by the middleware).
const getPostedContact = query(async (): Promise<ContactResult | null> => {
  "use server";
  return getRequestEvent()?.locals.contact ?? null;
}, "posted-contact");

const sendMessage = action(async (form: FormData): Promise<ContactResult> => {
  "use server";
  return processContact(readContactForm(form));
}, "send-message");

const empty: ContactValues = { name: "", email: "", message: "" };

export default function Contact() {
  const posted = createAsync(() => getPostedContact(), { deferStream: true });

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={posted() !== undefined}>
        <ContactForm initial={posted() ?? null} />
      </Show>
    </>
  );
}

function ContactForm(props: { initial: ContactResult | null }) {
  const initial = props.initial;
  const send = useAction(sendMessage);
  const [errors, setErrors] = createSignal<ContactErrors>(initial && !initial.ok ? initial.errors : {});
  const [sentName, setSentName] = createSignal<string | null>(initial?.ok ? initial.name : null);
  const [pending, setPending] = createSignal(false);
  const values = initial && !initial.ok ? initial.values : empty;

  const onSubmit = async (e: SubmitEvent) => {
    e.preventDefault();
    const formEl = e.currentTarget as HTMLFormElement;
    const form = new FormData(formEl);
    const clientErrors = validateContact(readContactForm(form));
    setSentName(null);
    setErrors(clientErrors);
    if (Object.keys(clientErrors).length > 0) return;
    setPending(true);
    try {
      const result = await send(form);
      if (result.ok) {
        setSentName(result.name);
        formEl.reset();
      } else {
        setErrors(result.errors);
      }
    } finally {
      setPending(false);
    }
  };

  return (
    <>
      <Show when={sentName() !== null}>
        <p role="status" class="success">{`Thanks, ${sentName()}! Your message has been sent.`}</p>
      </Show>
      <form method="post" action="/contact" novalidate onSubmit={onSubmit}>
        <div class="field">
          <label for="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            value={values.name}
            aria-invalid={errors().name ? "true" : undefined}
            aria-describedby={errors().name ? "contact-name-error" : undefined}
          />
          <Show when={errors().name}>
            <p id="contact-name-error" class="error">{errors().name}</p>
          </Show>
        </div>
        <div class="field">
          <label for="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            value={values.email}
            aria-invalid={errors().email ? "true" : undefined}
            aria-describedby={errors().email ? "contact-email-error" : undefined}
          />
          <Show when={errors().email}>
            <p id="contact-email-error" class="error">{errors().email}</p>
          </Show>
        </div>
        <div class="field">
          <label for="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={6}
            value={values.message}
            aria-invalid={errors().message ? "true" : undefined}
            aria-describedby={errors().message ? "contact-message-error" : undefined}
          />
          <Show when={errors().message}>
            <p id="contact-message-error" class="error">{errors().message}</p>
          </Show>
        </div>
        <button type="submit" disabled={pending()}>
          Send
        </button>
      </form>
    </>
  );
}
